import AlarmKit
import AppIntents
import Foundation

/// iOS reads App Intents metadata from the app target only, so the intent that
/// stops an alarm and opens Wupiko lives there (generated by plugins/ios-intents.js).
/// The app registers it at launch, and every scheduled alarm uses it as its stop action.
public enum WupikoAlarmIntents {
  nonisolated(unsafe) public static var stopAndOpen: ((UUID) -> any LiveActivityIntent)?
}
